package com.fitnutri.backend.records.workout;
import com.fitnutri.backend.common.*;
import com.fitnutri.backend.records.*;
import com.fitnutri.backend.activity.catalogue.ExerciseOptionService;
import com.fitnutri.backend.activity.catalogue.MovementCatalogueService;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import tools.jackson.databind.ObjectMapper;
import tools.jackson.core.type.TypeReference;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.namedparam.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
/** Server-paged roots and bounded bulk snapshots; never flatten a Workout into separate history cards. */
@Service @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
public class ExerciseEntryReadService{
 private final NamedParameterJdbcTemplate jdbc;private final WorkoutSnapshotReader snapshots;private final RecordDatePolicy dates;private final CanonicalV2Json canonical;private final ObjectMapper json;
 public ExerciseEntryReadService(JdbcTemplate jdbc,WorkoutSnapshotReader snapshots,RecordDatePolicy dates,CanonicalV2Json canonical,ObjectMapper json){this.jdbc=new NamedParameterJdbcTemplate(jdbc);this.snapshots=snapshots;this.dates=dates;this.canonical=canonical;this.json=json;}
 public record Key(String kind,long id){}
 public record MovementDetails(String catalogueId,String name,String loadBasis,Long setCount,Long repetitions,BigDecimal loadKg,boolean selectableForNew,MovementCatalogueService.Response catalogue){}
 public record PeriodDetails(UUID clientEntryId,String optionId,String name,boolean selectableForNew,List<MovementDetails>movements,ExerciseOptionService.Response option){}
 public record Root(String id,long version,LocalDate recordDate,String source,Instant createdAt,Instant updatedAt,DataQuality dataQuality,String displayName,Object input,Object preview,List<PeriodDetails>periodDetails,int periodCount){}
 public record Page(List<Root>results,long totalMatches,int page,int size,boolean hasMore){}
 private static final String PERIODS="SELECT e.*,o.option_key,o.revision AS option_revision,o.category AS option_category,o.allowed_details::text AS option_allowed_details,o.reference_id AS option_reference_id,o.mapping_evidence->>'reason' AS option_mapping_reason,o.active AS option_active,o.review_status AS option_review,o.mapping_kind AS current_mapping_kind,t.is_active AS reference_active,d.verified AS reference_verified FROM exercise_record e LEFT JOIN exercise_option o ON o.id=e.exercise_option_id LEFT JOIN exercise_type t ON t.id=o.reference_id LEFT JOIN activity_dataset d ON d.id=t.dataset_id ";
 public Page listRoots(Long owner,LocalDate from,LocalDate to,String zone,int page,int size){dates.requireRange(from,to,zone);if(page<0||size<1||size>100)throw BusinessException.invalid("page","Choose a nonnegative page and size from1 to100.");var args=new MapSqlParameterSource().addValue("owner",owner).addValue("from",from).addValue("to",to).addValue("limit",size).addValue("offset",(long)page*size);String cte="WITH roots AS(SELECT id,recorded_date,created_at,'quick' AS kind FROM exercise_record WHERE user_id=:owner AND workout_id IS NULL AND deleted_at IS NULL AND recorded_date BETWEEN :from AND :to UNION ALL SELECT id,recorded_date,created_at,'workout' AS kind FROM workout_record WHERE user_id=:owner AND deleted_at IS NULL AND recorded_date BETWEEN :from AND :to) ";long total=jdbc.queryForObject(cte+"SELECT count(*) FROM roots",args,Long.class);var keys=jdbc.query(cte+"SELECT id,kind FROM roots ORDER BY recorded_date DESC,created_at DESC,kind,id DESC LIMIT :limit OFFSET :offset",args,(r,n)->new Key(r.getString("kind"),r.getLong("id")));var rows=batchOwnedRoots(owner,keys);return new Page(rows,total,page,size,(long)page*size+rows.size()<total);}
 public Root getOwnedRoot(Long owner,String kind,long id){return batchOwnedRoots(owner,List.of(new Key(kind,id))).getFirst();}
 List<Root>batchOwnedRoots(Long owner,List<Key>keys){if(keys.size()>100||new HashSet<>(keys).size()!=keys.size())throw invalid();if(keys.isEmpty())return List.of();var quick=new ArrayList<Long>();var workout=new ArrayList<Long>();for(var key:keys){if(key.id()<1||!Set.of("quick","workout").contains(key.kind()==null?"":key.kind()))throw invalid();(key.kind().equals("quick")?quick:workout).add(key.id());}var rootRows=new HashMap<Key,Map<String,Object>>();var periodRows=new HashMap<Key,List<Map<String,Object>>>();var allPeriods=new ArrayList<Long>();
  if(!quick.isEmpty()){var args=new MapSqlParameterSource().addValue("owner",owner).addValue("ids",quick);for(var p:jdbc.queryForList(PERIODS+"WHERE e.user_id=:owner AND e.id IN (:ids) AND e.workout_id IS NULL AND e.deleted_at IS NULL",args)){var key=new Key("quick",number(p.get("id")));rootRows.put(key,p);periodRows.put(key,List.of(p));allPeriods.add(key.id());}}
  if(!workout.isEmpty()){var args=new MapSqlParameterSource().addValue("owner",owner).addValue("ids",workout);for(var r:jdbc.queryForList("SELECT * FROM workout_record WHERE user_id=:owner AND id IN (:ids) AND deleted_at IS NULL",args))rootRows.put(new Key("workout",number(r.get("id"))),r);for(var p:jdbc.queryForList(PERIODS+"WHERE e.user_id=:owner AND e.workout_id IN (:ids) AND e.deleted_at IS NULL ORDER BY e.workout_id,e.period_position,e.id",args)){var key=new Key("workout",number(p.get("workout_id")));periodRows.computeIfAbsent(key,k->new ArrayList<>()).add(p);allPeriods.add(number(p.get("id")));}}
  Map<Long,List<Map<String,Object>>>moves=new HashMap<>();if(!allPeriods.isEmpty()){var args=new MapSqlParameterSource().addValue("owner",owner).addValue("ids",allPeriods);for(var m:jdbc.queryForList("SELECT m.*,c.active AS movement_active,c.review_status AS movement_review,c.default_period_option_id,c.body_region,c.equipment_type,c.allowed_fields::text AS movement_allowed_fields FROM workout_movement_log m JOIN exercise_record e ON e.id=m.exercise_record_id JOIN movement_catalogue c ON c.id=m.movement_catalogue_id WHERE e.user_id=:owner AND e.id IN (:ids) AND e.deleted_at IS NULL ORDER BY m.exercise_record_id,m.position,m.id",args))moves.computeIfAbsent(number(m.get("exercise_record_id")),k->new ArrayList<>()).add(m);}
  var results=new ArrayList<Root>();for(var key:keys){var row=rootRows.get(key);if(row==null)throw missing();var ps=periodRows.getOrDefault(key,List.of());Object input,preview;if(key.kind().equals("quick")&&row.get("exercise_option_id")==null){input=unmappedInput(row);preview=unmappedPreview(row,input);}else{var stored=snapshots.fromRows(key.kind(),key.id(),row,ps,moves).root();input=contractInput(stored.input());preview=stored.preview();}var details=new ArrayList<PeriodDetails>();for(var p:ps){boolean selectable=selectable(p);var ms=moves.getOrDefault(number(p.get("id")),List.of()).stream().map(m->new MovementDetails(m.get("movement_catalogue_id").toString(),m.get("name_snapshot").toString(),m.get("load_basis_snapshot").toString(),nullableNumber(m.get("set_count")),nullableNumber(m.get("repetitions")),(BigDecimal)m.get("load_kg"),selectable&&Boolean.TRUE.equals(m.get("movement_active"))&&"REVIEWED".equals(m.get("movement_review"))&&Objects.equals(m.get("default_period_option_id"),p.get("exercise_option_id")),movementCatalogue(m))).toList();details.add(new PeriodDetails((UUID)p.get("client_entry_id"),identity(p.get("exercise_option_id")),Objects.toString(p.get("option_name_snapshot"),p.get("exercise_type").toString()),selectable,ms,ownedOption(p)));}results.add(new Root(Long.toString(key.id()),number(row.get("version")),((java.sql.Date)row.get("recorded_date")).toLocalDate(),RecordSource.valueOf(row.get("source").toString()).canonical().name(),((java.sql.Timestamp)row.get("created_at")).toInstant(),((java.sql.Timestamp)row.get("updated_at")).toInstant(),key.kind().equals("workout")?DataQuality.CURRENT:DataQuality.valueOf(row.get("data_quality").toString()),row.get(key.kind().equals("workout")?"title":"exercise_type").toString(),input,preview,List.copyOf(details),ps.size()));}return List.copyOf(results);
 }
 private ExerciseOptionService.Response ownedOption(Map<String,Object>p){if(p.get("exercise_option_id")==null)return null;return new ExerciseOptionService.Response(identity(p.get("exercise_option_id")),p.get("option_key").toString(),p.get("option_revision").toString(),p.get("option_name_snapshot").toString(),p.get("option_category").toString(),p.get("period_kind").toString(),p.get("current_mapping_kind").toString(),json.readValue(p.get("option_allowed_details").toString(),new TypeReference<List<String>>(){}),identity(p.get("option_reference_id")),p.get("option_mapping_reason").toString());}
 private MovementCatalogueService.Response movementCatalogue(Map<String,Object>m){return new MovementCatalogueService.Response(identity(m.get("movement_catalogue_id")),m.get("name_snapshot").toString(),m.get("body_region").toString(),m.get("equipment_type").toString(),m.get("load_basis_snapshot").toString(),identity(m.get("default_period_option_id")),json.readValue(m.get("movement_allowed_fields").toString(),new TypeReference<List<String>>(){}));}
 private Map<String,Object>unmappedInput(Map<String,Object>r){var p=new LinkedHashMap<String,Object>();p.put("clientEntryId",r.get("client_entry_id"));p.put("referenceId",identity(r.get("exercise_type_id")));p.put("exerciseName",r.get("exercise_type"));p.put("durationMinutes",r.get("duration_minutes"));p.put("legacyIntensity",r.get("intensity"));p.put("legacyEstimatedCalories",r.get("estimated_calories"));var input=new LinkedHashMap<String,Object>();input.put("kind","QUICK");input.put("clientEntryId",r.get("client_entry_id"));input.put("period",p);return Collections.unmodifiableMap(input);}
 /** Keep absent optional origin out of the public read shape without altering private canonical DTO hashing. */
 private Map<String,Object>contractInput(ExerciseEntryInputs.Entry stored){var result=json.readValue(json.writerFor(ExerciseEntryInputs.Entry.class).writeValueAsString(stored),new TypeReference<LinkedHashMap<String,Object>>(){});if(result.get("originWorkoutId")==null)result.remove("originWorkoutId");return Collections.unmodifiableMap(result);}
 private Map<String,Object>unmappedPreview(Map<String,Object>r,Object input){var p=new LinkedHashMap<String,Object>();p.put("clientEntryId",r.get("client_entry_id"));p.put("durationMinutes",r.get("duration_minutes"));String status=switch(r.get("estimate_status").toString()){case "AVAILABLE"->"AVAILABLE";case "MISSING_WEIGHT"->"NO_WEIGHT";case "NO_APPLICABLE_REFERENCE"->"UNSUPPORTED_REFERENCE";default->"LEGACY_UNVERIFIED";};p.put("status",status);p.put("estimatedKj",r.get("estimated_kj"));p.put("calculationFingerprint",canonical.hash("exercise-unmapped-stored-period-v2",storedAuthority(r)));p.put("unavailableReason",status.equals("AVAILABLE")?null:"Preserved historical activity; no current option or verified complete estimate is inferred.");var result=new LinkedHashMap<String,Object>();result.put("periods",List.of(p));result.put("totalMinutes",r.get("duration_minutes"));result.put("knownEnergyKj",r.get("estimated_kj"));result.put("partial",false);result.put("fingerprint",canonical.hash("exercise-unmapped-stored-preview-v2",p));result.put("inputSignature",canonical.hash("exercise-unmapped-stored-input-v2",input));return Collections.unmodifiableMap(result);}
 private static Map<String,Object>storedAuthority(Map<String,Object>r){var values=new LinkedHashMap<String,Object>();for(var k:List.of("client_entry_id","exercise_type_id","recorded_date","duration_minutes","estimated_kj","estimate_status","weight_kg_used","weight_date_used","met_used","formula_version"))values.put(k,r.get(k));return values;}
 private static boolean selectable(Map<String,Object>p){return Boolean.TRUE.equals(p.get("option_active"))&&"REVIEWED".equals(p.get("option_review"))&&("UNAVAILABLE".equals(p.get("current_mapping_kind"))||Boolean.TRUE.equals(p.get("reference_active"))&&Boolean.TRUE.equals(p.get("reference_verified")));}
 private static Long nullableNumber(Object value){return value==null?null:number(value);}private static long number(Object value){return ((Number)value).longValue();}private static String identity(Object value){return value==null?null:value.toString();}private static BusinessException missing(){return new BusinessException(HttpStatus.NOT_FOUND,"NOT_FOUND","Exercise entry not found.");}private static BusinessException invalid(){return BusinessException.invalid("id","Choose bounded distinct Quick or Workout roots.");}
}
